  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
`;

function writeAndExit(writer, message, code) {
  writer(`${message}\n`);
  process.exit(code);
}

function exitWithHelp() {
  writeAndExit((message) => process.stdout.write(message), HELP_TEXT.slice(0, -1), 0);
}

function exitWithParseError(message) {
  writeAndExit(
    (output) => process.stderr.write(output),
    `${USAGE_LINE}\n${PROGRAM_NAME}: error: ${message}`,
    2,
  );
}

function looksLikeNegativeNumber(token) {
  return /^-(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(token);
}

function isOptionLike(token) {
  return token.startsWith('-') && !looksLikeNegativeNumber(token);
}

function parseInteger(optionName, rawValue) {
  if (!/^[+-]?\d+$/.test(rawValue)) {
    exitWithParseError(`argument ${optionName}: invalid int value: ${pythonRepr(rawValue)}`);
  }

  return Number(rawValue);
}

export function parseTest15Args(argv = process.argv.slice(2)) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      exitWithHelp();
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const separatorIndex = token.indexOf('=');
      const optionName = separatorIndex === -1 ? token : token.slice(0, separatorIndex);
      const attachedValue = separatorIndex === -1 ? null : token.slice(separatorIndex + 1);

      if (optionName === '--a' || optionName === '--b' || optionName === '--c') {
        let rawValue = attachedValue;

        if (rawValue === null) {
          const nextToken = argv[index + 1];

          if (nextToken === undefined || isOptionLike(nextToken) || nextToken === '--') {
            exitWithParseError(`argument ${optionName}: expected one argument`);
          }

          rawValue = nextToken;
          index += 1;
        }

        if (optionName === '--a') {
          values.a = rawValue;
        } else if (optionName === '--b') {
          values.b = parseInteger(optionName, rawValue);
        } else {
          values.c = parseInteger(optionName, rawValue);
        }

        continue;
      }
    }

    extras.push(token);
  }

  const missing = [];

  if (!Object.prototype.hasOwnProperty.call(values, 'a')) {
    missing.push('--a');
  }

  if (!Object.prototype.hasOwnProperty.call(values, 'b')) {
    missing.push('--b');
